import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import type { ProductEnv } from './env';

const FRAGMENTS_ROOT = '_fragments';
export const INCLUDE_MAX_DEPTH = 16;
const INCLUDE_TOKEN_PATTERN = /__INCLUDE:([a-z0-9-]+)__/g;
const VALID_ID_PATTERN = /^[a-z0-9-]+$/;

function sourcePath(...segments: string[]): string {
  return join(process.cwd(), ...segments);
}

export function resolveFragment(id: string, env: ProductEnv): string {
  if (!VALID_ID_PATTERN.test(id)) {
    throw new Error(`Invalid fragment id "${id}": must match [a-z0-9-]+`);
  }
  const agentPath = join(FRAGMENTS_ROOT, `${id}.${env.agent}.md`);
  if (existsSync(sourcePath(agentPath))) return agentPath;
  const defaultPath = join(FRAGMENTS_ROOT, `${id}.md`);
  if (existsSync(sourcePath(defaultPath))) return defaultPath;
  throw new Error(
    `Missing fragment "${id}" for agent "${env.agent}" (looked for ${agentPath}, ${defaultPath})`,
  );
}

export function expandIncludes(
  text: string,
  env: ProductEnv,
  stack: readonly string[] = [],
  depth = 0,
): string {
  if (depth > INCLUDE_MAX_DEPTH) {
    throw new Error(`Include depth exceeded ${INCLUDE_MAX_DEPTH}: ${stack.join(' → ')}`);
  }

  INCLUDE_TOKEN_PATTERN.lastIndex = 0;
  return text.replace(INCLUDE_TOKEN_PATTERN, (_match, id: string) => {
    if (!VALID_ID_PATTERN.test(id)) {
      throw new Error(`Invalid include id "${id}" in token __INCLUDE:${id}__`);
    }
    if (stack.includes(id)) {
      throw new Error(`Include cycle detected: ${[...stack, id].join(' → ')}`);
    }

    const fragmentPath = resolveFragment(id, env);
    const fragmentBody = readFileSync(sourcePath(fragmentPath), 'utf-8');
    const expanded = expandIncludes(fragmentBody, env, [...stack, id], depth + 1);
    return expanded.trim();
  });
}

build/assert-no-tokens.ts.source:
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import type { ProductEnv } from './env';
import { requireProductEnv } from './env';
import { scanTextFiles } from './scan-files';

const NAME_TOKEN_PATTERN = /__(?:CALL_SKILL|CALL_AGENT|SKILL|AGENT|MCP|BIN):[a-z0-9_-]+__/;
const PATH_TOKEN_PATTERN = /__DEV_TEAM_(?:ROOT|RUNTIME_ROOT)__/;
const INCLUDE_TOKEN_PATTERN = /__INCLUDE:/;

export function assertNoNameTokens(rootDir: string, env: ProductEnv): void {
  if (rootDir == null || rootDir === '') {
    throw new Error('rootDir is required');
  }
  requireProductEnv(env);
  const leftovers: string[] = [];
  for (const rel of scanTextFiles(rootDir)) {
    const content = readFileSync(join(rootDir, rel), 'utf-8');
    if (NAME_TOKEN_PATTERN.test(content) || INCLUDE_TOKEN_PATTERN.test(content)) {
      leftovers.push(rel);
      continue;
    }
    // Plugin builds must clear path tokens at assemble time; home image may keep them.
    if (PATH_TOKEN_PATTERN.test(content)) {
      leftovers.push(rel);
    }
  }
  if (leftovers.length === 0) return;
  throw new Error(
    `[assemble:${env.agent} ${env.layout}] unresolved name-class tokens in:\n  - ${leftovers.join('\n  - ')}`,
  );
}

