export type AgentType = 'claude' | 'cursor';
export type ProductEnvKey = 'claude' | 'cursor' | 'cursorHome';
export type ProductLayout = 'plugin' | 'home-image';
export type PathReplacePhase = 'build' | 'install';

export interface ProductEnv extends ModelEnv, ToolEnv, SubAgentEnv {
  /** 适配agent */
  agent: AgentType;
  /** 产物形态 */
  layout: ProductLayout;
  /** 插件前缀 */
  pluginPrefix: string;
  /** 文件或工具名称的前缀，避免名称重复 */
  namePrefix: string;
  /** agent唤起mcp工具的前缀 */
  mcpToolPrefix: string;
  /** 产物目录 */
  outDir: string;
  /** hooks文件相对路径 */
  hooksFilePath: string;
  /** mcp文件相对路径 */
  mcpFilePath: string;
  /** 插件根目录 / cursor home目录 */
  pluginRoot: string;
}

interface ModelEnv {
  modelHigh: string;
  modelFast: string;
}

interface ToolEnv {
  toolWrite: string;
  toolEdit: string;
  toolBash: string;
  toolCmd: string;
  toolAskUser: string;
}

interface SubAgentEnv {
  agentGeneralPurpose: string;
}

export const PRODUCT_ENV_KEYS: ProductEnvKey[] = ['claude', 'cursor', 'cursorHome'];

const ENV_TABLE: Record<ProductEnvKey, ProductEnv> = {
  claude: {
    agent: 'claude',
    layout: 'plugin',
    pluginPrefix: 'dev-team:',
    namePrefix: '',
    mcpToolPrefix: 'mcp__plugin_dev-team_dev-team__',
    outDir: '../../claude-plugins/dev-team',
    hooksFilePath: 'hooks/hooks.json',
    mcpFilePath: '.mcp.json',
    pluginRoot: '${CLAUDE_PLUGIN_ROOT}',
    modelHigh: 'opus',
    modelFast: 'sonnet',
    toolWrite: 'Write',
    toolEdit: 'Edit',
    toolBash: 'Bash',
    toolCmd: 'PowerShell',
    toolAskUser: 'AskUserQuestion',
    agentGeneralPurpose: 'general-purpose',
  },
  cursor: {
    agent: 'cursor',
    layout: 'plugin',
    pluginPrefix: 'dev-team:',
    namePrefix: '',
    mcpToolPrefix: 'mcp__plugin_dev-team_dev-team__',
    outDir: '../../cursor-plugins/dev-team',
    hooksFilePath: 'hooks/hooks.json',
    mcpFilePath: 'mcp.json',
    pluginRoot: '.',
    modelHigh: 'inherit',
    modelFast: 'fast',
    toolWrite: 'Write',
    toolEdit: 'StrReplace',
    toolBash: 'Shell',
    toolCmd: 'Shell',
    toolAskUser: 'AskQuestion',
    agentGeneralPurpose: 'generalPurpose',
  },
  cursorHome: {
    agent: 'cursor',
    layout: 'home-image',
    pluginPrefix: '',
    namePrefix: 'dev-team_',
    mcpToolPrefix: 'mcp__user-dev-team_mcp__',
    outDir: '../../cursor-home-image/dev-team',
    hooksFilePath: 'hooks.json',
    mcpFilePath: 'mcp.json',
    pluginRoot: '__INSTALL_PLUGIN_ROOT__',
    modelHigh: 'inherit',
    modelFast: 'fast',
    toolWrite: 'Write',
    toolEdit: 'StrReplace',
    toolBash: 'Shell',
    toolCmd: 'Shell',
    toolAskUser: 'AskQuestion',
    agentGeneralPurpose: 'generalPurpose',
  },
};

export function getEnv(key: ProductEnvKey): ProductEnv {
  const env = ENV_TABLE[key];
  if (!env) {
    throw new Error(`Unknown product env key: ${String(key)}`);
  }
  return env;
}

/** Reject null/undefined/empty env objects missing required ProductEnv fields. */
export function requireProductEnv(env: ProductEnv): void {
  if (env == null || typeof env !== 'object' || !('agent' in env) || env.agent == null) {
    throw new Error('env is required');
  }
}

build/hooks-profile.ts.source:
import { z } from 'zod/v4';

import { applyEnvTokens } from './apply-env-tokens';
import { requireProductEnv, type ProductEnv } from './env';

const hooksCanonicalMatcherSchema = z.object({
  claude: z.string().nullable(),
  cursor: z.string().nullable(),
});

const hooksCanonicalPreToolUseSchema = z.object({
  matchers: hooksCanonicalMatcherSchema,
  commandTemplate: z.string(),
});

const hooksCanonicalSubagentStopSchema = z.object({
  matchers: hooksCanonicalMatcherSchema,
  loop_limit: z.number().optional(),
  commandTemplate: z.string(),
});

const hooksCanonicalSchema = z.object({
  description: z.string().optional(),
  preToolUse: z.array(hooksCanonicalPreToolUseSchema),
  subagentStop: z.array(hooksCanonicalSubagentStopSchema),
});

type HooksCanonical = z.infer<typeof hooksCanonicalSchema>;

/** Expand name/path tokens in canonical JSON before platform wrapping. */
function expandCanonical(canonical: HooksCanonical, env: ProductEnv): HooksCanonical {
  const expanded = applyEnvTokens(JSON.stringify(canonical), env);
  return JSON.parse(expanded);
}

/** Wrap already-expanded canonical into Claude Code plugin hooks.json shape. */
function buildClaudeNested(canonical: HooksCanonical): unknown {
  const hooks: Record<string, unknown> = {
    PreToolUse: canonical.preToolUse
      .filter((entry) => entry.matchers.claude)
      .map((entry) => ({
        matcher: entry.matchers.claude,
        hooks: [{ type: 'command', command: entry.commandTemplate }],
      })),
  };

  const subagentStop = canonical.subagentStop
    .filter((entry) => entry.matchers.claude)
    .map((entry) => ({
      matcher: entry.matchers.claude,
      hooks: [{ type: 'command', command: entry.commandTemplate }],
    }));
  if (subagentStop.length > 0) {
    hooks.SubagentStop = subagentStop;
  }

  return {
    description: canonical.description,
    hooks,
  };
}

/** Wrap already-expanded canonical into Cursor native/plugin hooks.json shape. */
function buildCursorNative(canonical: HooksCanonical): unknown {
  const hooks: Record<string, unknown> = {};

  const preToolUse = canonical.preToolUse
    .filter((entry) => entry.matchers.cursor)
    .map((entry) => ({
      matcher: entry.matchers.cursor,
      command: entry.commandTemplate,
    }));
  if (preToolUse.length > 0) {
    hooks.preToolUse = preToolUse;
  }

  const subagentStop = canonical.subagentStop
    .filter((entry) => entry.matchers.cursor)
    .map((entry) => ({
      matcher: entry.matchers.cursor,
      loop_limit: entry.loop_limit,
      command: entry.commandTemplate,
    }));
  if (subagentStop.length > 0) {
    hooks.subagentStop = subagentStop;
  }

  return {
    version: 1,
    hooks,
  };
}

export function buildHooksFile(canonical: object, env: ProductEnv): string {
  requireProductEnv(env);
  const parsed = hooksCanonicalSchema.parse(canonical);
  const expanded = expandCanonical(parsed, env);
  const doc = env.agent === 'claude' ? buildClaudeNested(expanded) : buildCursorNative(expanded);
  return `${JSON.stringify(doc, null, 2)}\n`;
}

build/assemble.test.ts.source:
/**
 * 单元测试: assemble.ts — 多平台产物组装
 */

import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import * as envMod from './env';

const tempRoots: string[] = [];
let outBase = '';
let cwdSpy: ReturnType<typeof vi.spyOn> | undefined;

function mockCwd(root: string): void {
  cwdSpy?.mockRestore();
  cwdSpy = vi.spyOn(process, 'cwd').mockReturnValue(root);
}

function makeOutDir(key: envMod.ProductEnvKey): string {
  const dir = join(outBase, key);
  mkdirSync(dir, { recursive: true });
  return dir;
}

vi.mock('./env', async (importOriginal) => {
  const actual = await importOriginal<typeof envMod>();
  return {
    ...actual,
    getEnv: (key: envMod.ProductEnvKey) => ({
      ...actual.getEnv(key),
      outDir: makeOutDir(key),
    }),
  };
});

const { assembleAll } = await import('./assemble');

function writeMinimalCanonical(root: string): void {
  mkdirSync(join(root, 'hooks'), { recursive: true });
  writeFileSync(
    join(root, 'hooks/hooks.canonical.json'),
    JSON.stringify(
      {
        preToolUse: [
          {
            matchers: { claude: 'Write', cursor: 'Write' },
            commandTemplate: 'node "__DEV_TEAM_ROOT__/bin/__BIN:hooks__" protect-files',
          },
        ],
        subagentStop: [
          {
            matchers: { claude: '__CALL_AGENT:implementation-generator__', cursor: null },
            loop_limit: 5,
            commandTemplate: 'node "__DEV_TEAM_ROOT__/bin/__BIN:hooks__" static-check',
          },
        ],
      },
      null,
      2,
    ),
  );
}

function writeMinimalStaging(root: string): void {
  mkdirSync(join(root, '.pack-staging/bin'), { recursive: true });
  writeFileSync(join(root, '.pack-staging/bin/cli.cjs'), '// stub\n');
  writeFileSync(join(root, '.pack-staging/install.mjs'), 'export {};\n');
}

function writeMinimalTree(root: string): void {
  writeMinimalCanonical(root);
  writeMinimalStaging(root);
  mkdirSync(join(root, 'templates'), { recursive: true });
  mkdirSync(join(root, 'utils'), { recursive: true });
  mkdirSync(join(root, 'agents'), { recursive: true });
  mkdirSync(join(root, '_fragments'), { recursive: true });
  writeFileSync(
    join(root, '_fragments/static-analysis-gate.cursor.md'),
    'run_static_analysis gate\n',
  );
  writeFileSync(join(root, '_fragments/static-analysis-gate.md'), '');
  writeFileSync(
    join(root, 'agents/implementation-generator.md'),
    '# gen\n\n__INCLUDE:static-analysis-gate__\n',
  );
}

beforeEach(() => {
  outBase = mkdtempSync(join(tmpdir(), 'assemble-out-'));
  tempRoots.push(outBase);
});

afterEach(() => {
  cwdSpy?.mockRestore();
  cwdSpy = undefined;
  vi.clearAllMocks();
  while (tempRoots.length > 0) {
    const dir = tempRoots.pop();
    if (dir) rmSync(dir, { recursive: true, force: true });
  }
});

describe('assembleAll', () => {
  it('三平台 outDir 均生成且无残留 __INCLUDE:', async () => {
    await assembleAll();
    for (const key of envMod.PRODUCT_ENV_KEYS) {
      const outDir = makeOutDir(key);
      const env = envMod.getEnv(key);
      const agentRel =
        key === 'cursorHome'
          ? 'agents/dev-team_implementation-generator.md'
          : 'agents/implementation-generator.md';
      expect(existsSync(outDir)).toBe(true);
      for (const rel of [agentRel, env.hooksFilePath]) {
        const full = join(outDir, rel);
        expect(existsSync(full)).toBe(true);
        const content = readFileSync(full, 'utf-8');
        expect(content).not.toContain('__INCLUDE:');
      }
    }
  });

  it('Cursor/cursorHome outDir 的 hooks JSON 无 subagentStop 键', async () => {
    await assembleAll();
    for (const key of ['cursor', 'cursorHome'] as const) {
      const hooksPath = join(makeOutDir(key), envMod.getEnv(key).hooksFilePath);
      const parsed = JSON.parse(readFileSync(hooksPath, 'utf-8')) as {
        hooks: Record<string, unknown>;
      };
      expect(Object.hasOwn(parsed.hooks, 'subagentStop')).toBe(false);
    }
  });

  it('Claude outDir hooks 含 SubagentStop 且 command 含 static-check', async () => {
    await assembleAll();
    const hooksPath = join(makeOutDir('claude'), envMod.getEnv('claude').hooksFilePath);
    const parsed = JSON.parse(readFileSync(hooksPath, 'utf-8')) as {
      hooks: { SubagentStop: Array<{ hooks: Array<{ command: string }> }> };
    };
    expect(parsed.hooks.SubagentStop.length).toBeGreaterThan(0);
    expect(parsed.hooks.SubagentStop[0]?.hooks[0]?.command).toContain('static-check');
  });

  it('generator 引用缺失 fragment 时 assemble 失败', async () => {
    const root = mkdtempSync(join(tmpdir(), 'assemble-fixture-'));
    tempRoots.push(root);
    writeMinimalTree(root);
    writeFileSync(join(root, 'agents/broken-agent.md'), '__INCLUDE:missing-fragment__\n');
    mockCwd(root);
    await expect(assembleAll()).rejects.toThrow();
  });

  it('fragment 环引用时 assemble 失败', async () => {
    const root = mkdtempSync(join(tmpdir(), 'assemble-cycle-'));
    tempRoots.push(root);
    writeMinimalTree(root);
    writeFileSync(join(root, '_fragments/loop-a.md'), '__INCLUDE:loop-b__');
    writeFileSync(join(root, '_fragments/loop-b.md'), '__INCLUDE:loop-a__');
    writeFileSync(join(root, 'agents/cycle-agent.md'), '__INCLUDE:loop-a__\n');
    mockCwd(root);
    await expect(assembleAll()).rejects.toThrow(/Include cycle|Include depth/);
  });

  it('_fragments/ 存在于源码树但不出现在任一 env.outDir', async () => {
    await assembleAll();
    for (const key of envMod.PRODUCT_ENV_KEYS) {
      expect(existsSync(join(makeOutDir(key), '_fragments'))).toBe(false);
    }
  });

  it('Claude generator 无 run_static_analysis；Cursor 产物含该步骤', async () => {
    await assembleAll();
    const claudeAgent = readFileSync(
      join(makeOutDir('claude'), 'agents/implementation-generator.md'),
      'utf-8',
    );
    expect(claudeAgent).not.toContain('run_static_analysis');

    for (const key of ['cursor', 'cursorHome'] as const) {
      const prefix = key === 'cursorHome' ? 'dev-team_' : '';
      const agent = readFileSync(
        join(makeOutDir(key), `agents/${prefix}implementation-generator.md`),
        'utf-8',
      );
      expect(agent).toContain('run_static_analysis');
    }
  });

  it('assemble 复制 templates 与 utils 静态资源到各 outDir', async () => {
    await assembleAll();
    for (const key of envMod.PRODUCT_ENV_KEYS) {
      const outDir = makeOutDir(key);
      expect(existsSync(join(outDir, 'templates'))).toBe(true);
      expect(existsSync(join(outDir, 'utils'))).toBe(true);
    }
  });

  it('PRODUCT_ENV_KEYS 单轮全量执行失败即抛错', async () => {
    const root = mkdtempSync(join(tmpdir(), 'assemble-fail-fast-'));
    tempRoots.push(root);
    writeMinimalTree(root);
    rmSync(join(root, '_fragments/static-analysis-gate.md'));
    rmSync(join(root, '_fragments/static-analysis-gate.cursor.md'));
    mockCwd(root);
    await expect(assembleAll()).rejects.toThrow();
  });
});

